from datetime import datetime, time, timedelta
from decimal import Decimal, InvalidOperation
import math

import config


def price_from_rappen(rappen):
    """Return exact Decimal francs from integer Rappen, or None for an unknown price."""
    if rappen is None:
        return None
    if type(rappen) is not int or rappen < 0:
        raise ValueError('Price in Rappen must be a non-negative integer.')
    return Decimal(rappen) / config.RAPPEN_PER_FRANC


def _validated_price(value):
    """Validate a non-negative finite Decimal, accepting decimal strings but never floats."""
    if isinstance(value, str):
        try:
            value = Decimal(value)
        except InvalidOperation as error:
            raise ValueError('Price must be a decimal number.') from error
    if value is None:
        return None
    if not isinstance(value, Decimal) or not value.is_finite() or value < 0:
        raise ValueError('Price must be a non-negative Decimal or decimal string.')
    return value


def price_to_rappen(price):
    """Return integer Rappen, rejecting fractions of a cent instead of truncating them."""
    value = _validated_price(price)
    if value is None:
        return None
    # Course: L02 – Decimal preserves exact monetary amounts.
    rappen = value * config.RAPPEN_PER_FRANC
    if rappen != rappen.to_integral_value():
        raise ValueError('Price must contain whole Rappen.')
    return int(rappen)


class _Interval:
    """Share validated local interval boundaries across events, busy blocks and gaps."""

    def __init__(self, start, end):
        """Initialize a positive half-open interval using naive Zurich datetimes."""
        self._end = None
        self.start = start
        self.end = end

    # Course: U05 s2 – property setters keep invariants valid after construction too.
    @property
    def start(self):
        """Return the inclusive local start."""
        return self._start

    @start.setter
    def start(self, value):
        """Reject an invalid start without changing the last valid value."""
        _validate_datetime(value)
        if self._end is not None and value >= self._end:
            raise ValueError('End time must be after start time.')
        self._start = value

    @property
    def end(self):
        """Return the exclusive local end."""
        return self._end

    @end.setter
    def end(self, value):
        """Require an end strictly after the start."""
        _validate_datetime(value)
        if value <= self.start:
            raise ValueError('End time must be after start time.')
        self._end = value

    def duration_minutes(self):
        """Return the interval duration in whole minutes."""
        return int((self.end - self.start).total_seconds() // 60)


def _validate_datetime(value):
    """Require the internal time representation from SPEC section 4.5."""
    if not isinstance(value, datetime) or value.tzinfo is not None:
        raise ValueError('Time must be a naive Europe/Zurich datetime.')


class Event(_Interval):
    """Represent one dated occurrence with validated time, location, status and money."""

    SOURCE = 'generic'

    def __init__(self, event_id, series_id, title, start, end, location, location_type,
                 direction_key, bundle_key, bundle_name, description='', organizer='',
                 event_type='', source_url='', registration_url='', price=None,
                 members_only=False, end_is_estimated=False, status='open',
                 is_recurring=False, club_id=None):
        """Store the public occurrence fields defined in SPEC section 5.1."""
        # Course: L05 – inheritance reuses interval validation.
        super().__init__(start, end)
        self.event_id, self.series_id, self.title = event_id, series_id, title
        self.location, self.location_type = location, location_type
        self.direction_key = direction_key
        self.bundle_key, self.bundle_name = bundle_key, bundle_name
        self.description, self.organizer, self.event_type = description, organizer, event_type
        self.source_url, self.registration_url = source_url, registration_url
        self.price, self.status = price, status
        self.members_only, self.end_is_estimated = members_only, end_is_estimated
        self.is_recurring, self.club_id = is_recurring, club_id

    @property
    def price(self):
        """Return Decimal francs or None."""
        return self._price

    @price.setter
    def price(self, value):
        """Validate before assigning, preserving the old value if validation fails."""
        value = _validated_price(value)
        price_to_rappen(value)
        self._price = value

    @property
    def location_type(self):
        """Return the location classification used for placement."""
        return self._location_type

    @location_type.setter
    def location_type(self, value):
        """Require one supported location type."""
        if value not in config.LOCATION_TYPES:
            raise ValueError('Invalid location_type.')
        self._location_type = value

    @property
    def status(self):
        """Return the normalized source status."""
        return self._status

    @status.setter
    def status(self, value):
        """Preserve full/closed statuses as valid stored states."""
        if value not in config.EVENT_STATUSES:
            raise ValueError('Invalid event status.')
        self._status = value

    def is_multi_day(self):
        """Treat an ending exactly at midnight as belonging to the preceding day."""
        last = self.end.date()
        if self.end.time() == time.min:
            last -= timedelta(days=1)
        return self.start.date() != last

    def overlap_minutes(self, start, end):
        """Return the minutes shared with another half-open interval."""
        return max(0, (min(self.end, end) - max(self.start, start)).total_seconds() / 60)

    def source_label(self):
        """Return the generic organizer label."""
        return self.organizer

    def price_label(self):
        """Distinguish an unknown price, a free event and a paid event."""
        if self.price is None:
            return ''
        return 'Free' if self.price.is_zero() else f'CHF {self.price:.2f}'

    def display_tags(self):
        """Return the concise metadata tags required by SPEC section 5.1."""
        tags = []
        if self.end_is_estimated:
            tags.append('Estimated end')
        if self.members_only or self.status == 'members_only':
            tags.append('Members only')
        if self.price_label():
            tags.append(self.price_label())
        if self.status == 'apply':
            tags.append('Apply')
        if self.location_type == 'tba':
            tags.append('Location TBA')
        return tags

    def __str__(self):
        """Return a readable Swiss date/time label."""
        return f'{self.title} · {self.start:%a %d.%m. %H:%M}–{self.end:%H:%M}'

    def __repr__(self):
        """Return the public occurrence identity."""
        return f'{self.__class__.__name__}(event_id={self.event_id}, title={self.title!r})'


class UnisportCourse(Event):
    """Represent one session of a Unisport course."""

    SOURCE = 'unisport'

    def __init__(self, sport='', level='', **kwargs):
        """Add sport and level to the common event fields."""
        super().__init__(**kwargs)
        self.sport, self.level = sport, level

    def source_label(self):
        """Return the public Unisport name."""
        return 'Unisport HSG'

    def display_tags(self):
        """Extend common metadata with the course level."""
        return super().display_tags() + ([self.level] if self.level else [])


class ClubEvent(Event):
    """Represent one activity supplied by a student club."""

    SOURCE = 'uniclubs'

    def __init__(self, club_name='', club_category='', **kwargs):
        """Add the source club fields."""
        super().__init__(**kwargs)
        self.club_name, self.club_category = club_name, club_category

    def source_label(self):
        """Return the organizing club name."""
        return self.club_name

    def display_tags(self):
        """Extend common metadata with the event type."""
        return super().display_tags() + ([self.event_type] if self.event_type else [])


class CityEvent(Event):
    """Represent one city listing."""

    SOURCE = 'city'

    def __init__(self, venue='', **kwargs):
        """Add the city venue."""
        super().__init__(**kwargs)
        self.venue = venue

    def source_label(self):
        """Return the public city-source name."""
        return 'St.Gallen city events'


class BusyBlock(_Interval):
    """Represent a private in-memory interval that is never persisted to SQLite."""

    def __init__(self, start, end, title='', is_weekwise=False, weekwise_event_id=None):
        """Store optional calendar display metadata with the validated boundaries."""
        super().__init__(start, end)
        self.title = title
        self.is_weekwise, self.weekwise_event_id = is_weekwise, weekwise_event_id

    def __str__(self):
        """Return times without exposing a private title in diagnostic text."""
        return f'Busy {self.start:%H:%M}–{self.end:%H:%M}'


class Gap(_Interval):
    """Represent one free interval and its stable grid identifier."""

    def __init__(self, day, start, end):
        """Require the gap date to match its start date."""
        super().__init__(start, end)
        if day != start.date():
            raise ValueError('Gap day must match its start date.')
        self.day, self.gap_id = day, start.strftime(config.GAP_ID_FORMAT)

    def fits(self, event, tolerance_minutes=config.OVERLAP_TOLERANCE_MINUTES):
        """Accept at most the configured overlap at each end (SPEC section 10)."""
        if tolerance_minutes < 0:
            raise ValueError('Overlap tolerance must not be negative.')
        tolerance = timedelta(minutes=tolerance_minutes)
        return event.start >= self.start - tolerance and event.end <= self.end + tolerance

    def label(self):
        """Return a Swiss time range and compact duration."""
        minutes = self.duration_minutes()
        duration = f'{minutes // 60} h' if minutes % 60 == 0 else f'{minutes} min'
        return f'Free {self.start:%H:%M}–{self.end:%H:%M} ({duration})'


class Suggestion:
    """Compose an event with a validated score and human-readable reasons."""

    def __init__(self, event, score, reasons, friends_going=0, invited_by=None):
        """Initialize suggestion metadata without running a recommender."""
        self.event, self.score, self.reasons = event, score, list(reasons)
        self.friends_going, self.invited_by = friends_going, invited_by

    @property
    def score(self):
        """Return the normalized score."""
        return self._score

    @score.setter
    def score(self, value):
        """Reject nonfinite and out-of-range scores."""
        if not isinstance(value, (int, float)) or not math.isfinite(value) or not 0 <= value <= 1:
            raise ValueError('Score must be between zero and one.')
        self._score = value

    def match_label(self):
        """Return a whole percentage label."""
        return f'Match {self.score:.0%}'.replace('%', ' %')

    def is_invited(self):
        """Return whether an invitation accompanies the suggestion."""
        return self.invited_by is not None


class UserProfile:
    """Hold the user's focus and independent series, club and bundle favorite sets."""

    def __init__(self, user_id, display_name, friend_code, directions,
                 favorite_series_ids=None, favorite_club_ids=None, favorite_bundle_keys=None):
        """Copy mutable collections so profiles cannot accidentally share their favorites."""
        self.user_id, self.display_name, self.friend_code = user_id, display_name, friend_code
        # Course: L04 – membership tests use sets.
        self.directions = set(directions)
        if not self.directions.issubset(config.DIRECTION_COLORS):
            raise ValueError('Unknown focus direction.')
        self.favorite_series_ids = set(favorite_series_ids or [])
        self.favorite_club_ids = set(favorite_club_ids or [])
        self.favorite_bundle_keys = set(favorite_bundle_keys or [])

    @property
    def display_name(self):
        """Return the trimmed display name."""
        return self._display_name

    @display_name.setter
    def display_name(self, value):
        """Require two to twenty printable characters."""
        if not isinstance(value, str):
            raise ValueError('Display name must be text.')
        value = value.strip()
        if not config.DISPLAY_NAME_MIN <= len(value) <= config.DISPLAY_NAME_MAX:
            raise ValueError('Display name must contain 2–20 characters.')
        if not value.isprintable():
            raise ValueError('Display name must contain visible characters.')
        self._display_name = value

    def wants_direction(self, event):
        """Return whether the event belongs to the chosen focus directions."""
        return event.direction_key in self.directions

    def favorite_kinds(self, event):
        """Return matching series, club and bundle favorite kinds."""
        matches = []
        if event.series_id in self.favorite_series_ids:
            matches.append('series')
        if event.club_id in self.favorite_club_ids:
            matches.append('club')
        if event.bundle_key in self.favorite_bundle_keys:
            matches.append('bundle')
        return matches


def event_from_row(row):
    """Build a source subclass from a joined SQLite/API row containing its event ID."""
    classes = {'unisport': UnisportCourse, 'uniclubs': ClubEvent, 'city': CityEvent}
    if row['source'] not in classes:
        raise ValueError('Unknown event source.')
    values = {}
    for field in config.EVENT_ROW_FIELDS:
        values[field] = row[field]
    values['event_id'] = int(row['id'])
    values['start'] = datetime.strptime(row['start_time'], config.DB_TIME_FORMAT)
    values['end'] = datetime.strptime(row['end_time'], config.DB_TIME_FORMAT)
    rappen = row['price_rappen']
    if rappen is None or (isinstance(rappen, float) and math.isnan(rappen)):
        rappen = None
    else:
        rappen = int(rappen)
    values['price'] = price_from_rappen(rappen)
    club_id = values['club_id']
    values['club_id'] = None if club_id is None or math.isnan(float(club_id)) else int(club_id)
    for field in ('members_only', 'end_is_estimated', 'is_recurring'):
        values[field] = bool(values[field])
    if row['source'] == 'unisport':
        values.update(sport=row['sport'], level=row['level'])
    elif row['source'] == 'uniclubs':
        values.update(club_name=row['club_name'], club_category=row['club_category'])
    else:
        values['venue'] = row['location']
    return classes[row['source']](**values)
